/// Reverse a slice of chars into a fresh Vec<char>.
#[verifier::external(false)]   // turn on verification
#[requires(true)]
#[ensures(result.len() == a.len())]
#[ensures(forall(|i: usize| i < a.len() ==> result[i] == a[a.len() - 1 - i]))]
pub fn reverse(a: &[char]) -> Vec<char> {
    // Pre‐allocate a vector with the same length as the input slice
    let mut b = Vec::with_capacity(a.len());

    // Loop over the input slice in reverse.  We maintain the invariant
    //   1) b.len() never exceeds a.len()
    //   2) for all j < b.len(), b[j] == a[a.len() - 1 - j]
    // and we measure termination by a.len() - b.len().
    #[invariant(b.len() <= a.len())]
    #[invariant(forall(|j: usize| j < b.len() ==> b[j] == a[a.len() - 1 - j]))]
    #[decreases(a.len() - b.len())]
    for &ch in a.iter().rev() {
        b.push(ch);
    }

    b
}

